-- Phion: Hp Ahmad work progress report 13 Oct 2026 -> Projects board (projects + project_tasks). WRITE-ONLY, rerun-safe.
-- Run phion_hp_ahmad_check_20261013.sql first (expect exactly 1 tenant + 1 employee). Plain SQL, no functions.
-- Guard: tenant (name/code ILIKE %phion%) and employee (name/nickname ILIKE %ahmad%) used only if EXACTLY one match, else 0 rows.
-- Mapping: completed=done(100) | in progress=progress | not started=backlog | next plan=backlog+due (next week = 23 Oct 2026)
--          blockers=progress + tag Halangan + urgent/important | proposals=review + tag Cadangan (awaiting approval).
with t as (select id from public.tenants where (name ilike '%phion%' or code ilike '%phion%') and deleted_at is null),
t1 as (select id from t where (select count(*) from t) = 1)
insert into public.projects (tenant_id, name, kind)
select t1.id, 'Phion Visibility & Sales – Hp Ahmad', 'internal' from t1
where not exists (select 1 from public.projects p where p.tenant_id = t1.id and p.name = 'Phion Visibility & Sales – Hp Ahmad' and p.deleted_at is null);
with t as (select id from public.tenants where (name ilike '%phion%' or code ilike '%phion%') and deleted_at is null),
t1 as (select id from t where (select count(*) from t) = 1),
e as (select x.id from public.employees x join t1 on x.tenant_id = t1.id where x.deleted_at is null and (x.name ilike '%ahmad%' or x.nickname ilike '%ahmad%')),
e1 as (select id from e where (select count(*) from e) = 1),
p as (select pr.id, pr.tenant_id from public.projects pr join t1 on pr.tenant_id = t1.id where pr.name = 'Phion Visibility & Sales – Hp Ahmad' and pr.deleted_at is null limit 1)
insert into public.project_tasks (tenant_id, project_id, title, column_key, tag, assignee_employee_id, start_date, due_date, progress, notes, sort_order, is_important, is_urgent)
select p.tenant_id, p.id, v.title, v.col, v.tag, e1.id, v.sd::date, v.dd::date, v.pg, v.notes, v.so, v.imp, v.urg
from p cross join e1 cross join (values
  ('1a Kertas Cadangan Modul – Program Administration Course', 'done', 'Selesai', '2026-10-07', null, 100, 'Source: Hp Ahmad work progress report 13 Oct 2026 (for Mike). Kertas Cadangan Pelaksanaan Modul – Program Administration Course (Projek TUBE: Administration & Back Office Support for Asnaf Entrepreneurs). Status: Completed & Handed Over. Boss Phubieyas confirmed she will take it from here on 7 Oct 2026.', 1, false, false),
  ('1b SMIC 2026 – SME Conference Report', 'done', 'Selesai', '2026-10-08', null, 100, 'Source: Hp Ahmad work progress report 13 Oct 2026 (for Mike). SMIC 2026 – SME Conference Report. Date: 8 Oct 2026, Bukit Kiara M Resort & Hotel. Attendee: Last Born Gen X (1980) – SME Owner. Theme: SCALE - Talent, Capital, Tech. Status: Report completed.', 2, false, false),
  ('1c Quotations & Client Approach (Shamsul, Danny''s CKT)', 'done', 'Selesai', '2026-10-02', null, 100, 'Source: Hp Ahmad work progress report 13 Oct 2026 (for Mike). Quotations & Client Approach. Mr. Shamsul: quotation given on 7 Oct 2026, currently in negotiation stage. Danny''s Char Kuey Teow: quotation given on 2 Oct 2026.', 3, false, false),
  ('1d Phion TikTok Visibility – Initial Setup', 'done', 'Selesai', '2026-10-13', null, 100, 'Source: Hp Ahmad work progress report 13 Oct 2026 (for Mike). Account @phion.the.bookkee (393 Following, 54 Followers, 434 Likes). Followed 393 accounts; after filtering minus 12, 100% are PMKS/SME target audience; all approached with info that we are Phion. Content: highest video 1,922 views (pinned: Pakej Startup RM1 Sehari); average 300-1,000 views. Compliance: stopped IG & FB marketing as instructed; 100% TikTok focus (marketing team handles IG/FB).', 4, false, false),
  ('2a Alam''s Kitchen – BK Health Check follow-up', 'progress', null, '2026-10-13', null, 50, 'Source: Hp Ahmad work progress report 13 Oct 2026 (for Mike). Alam''s Kitchen: BK Health Check has been sent. Currently in discussion / follow-up stage.', 5, false, false),
  ('2b TikTok Growth Campaign (targeted PMKS following)', 'progress', null, '2026-10-13', null, 79, 'Source: Hp Ahmad work progress report 13 Oct 2026 (for Mike). Actively growing targeted PMKS following. Currently at 393 following, progressing to target 500 by 31 Oct 2026 (progress = 393/500).', 6, false, false),
  ('2c Quotation follow-up – Mr. Shamsul (closing)', 'progress', null, '2026-10-13', null, 50, 'Source: Hp Ahmad work progress report 13 Oct 2026 (for Mike). Following up with Mr. Shamsul for closing (quotation given 7 Oct 2026, in negotiation).', 7, false, false),
  ('3a Closing Danny''s Char Kuey Teow', 'backlog', null, '2026-10-13', null, 0, 'Source: Hp Ahmad work progress report 13 Oct 2026 (for Mike). No response received yet (quotation given 2 Oct 2026). Need to initiate follow-up call/message strategy.', 8, false, false),
  ('3b TikTok structured content calendar', 'backlog', null, '2026-10-13', null, 0, 'Source: Hp Ahmad work progress report 13 Oct 2026 (for Mike). Need to create weekly content pillar plan to increase followers, not just following.', 9, false, false),
  ('4.1 Follow-up call Danny''s CKT & Alam''s Kitchen', 'backlog', 'Plan', '2026-10-13', '2026-10-15', 0, 'Source: Hp Ahmad work progress report 13 Oct 2026 (for Mike). By 15 Oct 2026: follow-up call with Danny''s Char Kuey Teow & Alam''s Kitchen to push for closing.', 10, false, false),
  ('4.2 TikTok followers 54 → 150+', 'backlog', 'Plan', '2026-10-13', '2026-10-20', 0, 'Source: Hp Ahmad work progress report 13 Oct 2026 (for Mike). By 20 Oct 2026: increase TikTok followers from 54 to 150+ via daily 1 educational video (Tip, Habit, RM1 Sehari series) + comment on PMKS videos.', 11, false, false),
  ('4.3 500 targeted PMKS following + 1 video 5K views', 'backlog', 'Plan', '2026-10-13', '2026-10-31', 0, 'Source: Hp Ahmad work progress report 13 Oct 2026 (for Mike). By 31 Oct 2026: achieve 500 targeted PMKS following (target set by Mike) and aim for 1 video to reach 5K views.', 12, false, false),
  ('4.4 Propose 3 new content hooks', 'backlog', 'Plan', '2026-10-13', '2026-10-23', 0, 'Source: Hp Ahmad work progress report 13 Oct 2026 (for Mike). Next week (due set to Fri 23 Oct 2026): propose 3 new content hooks: Founder Story, Client Testimonial (if any), "Kesilapan Bookkeeping Peniaga".', 13, false, false),
  ('5a Halangan: Danny''s CKT tiada respons', 'progress', 'Halangan', '2026-10-13', null, 0, 'Source: Hp Ahmad work progress report 13 Oct 2026 (for Mike). No response on Danny''s Char Kuey Teow quotation since 2 Oct 2026. Need advice on second approach script.', 14, true, true),
  ('5b Halangan: kejelasan peranan marketing (IG/FB)', 'progress', 'Halangan', '2026-10-13', null, 0, 'Source: Hp Ahmad work progress report 13 Oct 2026 (for Mike). Told not to pursue IG/FB and focus only on TikTok because marketing team will do it. Need clarity: should I still provide leads/content to marketing team or be fully hands-off?', 15, true, true),
  ('5c Halangan: strategi conversion TikTok', 'progress', 'Halangan', '2026-10-13', null, 0, 'Source: Hp Ahmad work progress report 13 Oct 2026 (for Mike). Views exist (1.9k) but low conversion to followers (54) and WhatsApp inquiry. Need support on CTA strategy and perhaps link-in-bio optimisation.', 16, true, true),
  ('6.1 Cadangan: TikTok Live 2x seminggu', 'review', 'Cadangan', '2026-10-13', null, 0, 'Source: Hp Ahmad work progress report 13 Oct 2026 (for Mike). TikTok Live 2x a week (30 min), title "Tanya Phion: Cukai & Akaun Peniaga". TikTok pushes Live to PMKS FYP. Awaiting Mike approval to proceed.', 17, false, false),
  ('6.2 Cadangan: Stitch/Duet strategy', 'review', 'Cadangan', '2026-10-13', null, 0, 'Source: Hp Ahmad work progress report 13 Oct 2026 (for Mike). Duet with viral PMKS TikTokers (e.g. peniaga pasar) and give a free 1-min akaun tip. Awaiting Mike approval to proceed.', 18, false, false),
  ('6.3 Cadangan: Offline-to-Online', 'review', 'Cadangan', '2026-10-13', null, 0, 'Source: Hp Ahmad work progress report 13 Oct 2026 (for Mike). Every quotation, even if not closed, ask them to follow TikTok for free tips – builds KLT. Awaiting Mike approval to proceed.', 19, false, false),
  ('6.4 Cadangan: WhatsApp Channel + TikTok QR', 'review', 'Cadangan', '2026-10-13', null, 0, 'Source: Hp Ahmad work progress report 13 Oct 2026 (for Mike). Put TikTok QR on quotation PDF (WhatsApp Channel + TikTok). Awaiting Mike approval to proceed.', 20, false, false)
) as v(title, col, tag, sd, dd, pg, notes, so, imp, urg)
where not exists (select 1 from public.project_tasks k where k.project_id = p.id and k.title = v.title and k.deleted_at is null);
